{
  "name": "INHECO培养振荡单元",
  "name_en": "INHECO incubator shaker unit",
  "manufacturer": "INHECO",
  "description": "一种用于微孔板等实验耗材的培养振荡模块，集成加热控温、平面振荡以及抽屉式装载机构，可作为堆叠系统中的单个单元使用，常用于样品孵育、混匀和温控处理。",
  "description_en": "A microplate incubator-shaker module with heating, temperature control, planar shaking, and a drawer-based loading mechanism. It is used as an individual unit in a stacked system for sample incubation, mixing, and temperature-controlled processing.",
  "tag_hints": [
    "microplate incubation",
    "orbital shaking",
    "temperature control",
    "stacked automation module",
    "drawer-based plate loading",
    "labware detection"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭装载托盘并关闭培养舱门。",
      "description_en": "Close the loading tray and shut the incubator door."
    },
    {
      "action_name": "auto-initialize",
      "description": "对单元执行上电后的初始化。",
      "description_en": "Initialize the unit after power-on."
    },
    {
      "action_name": "auto-is_shaking_enabled",
      "description": "获取振荡是否已启用。",
      "description_en": "Get whether shaking is enabled."
    },
    {
      "action_name": "auto-is_temperature_control_enabled",
      "description": "获取温度控制是否已启用。",
      "description_en": "Get whether temperature control is enabled."
    },
    {
      "action_name": "auto-open",
      "description": "打开培养舱门并伸出装载托盘。",
      "description_en": "Open the incubator door and extend the loading tray."
    },
    {
      "action_name": "auto-perform_self_test",
      "description": "执行设备内部自检。",
      "description_en": "Run the device self-test."
    },
    {
      "action_name": "auto-request_delta_temperature",
      "description": "获取目标温度与实际温度之间的差值。",
      "description_en": "Get the difference between target and actual temperature."
    },
    {
      "action_name": "auto-request_drawer_cycles_performed",
      "description": "获取抽屉已执行的开合循环次数。",
      "description_en": "Get the number of drawer open/close cycles performed."
    },
    {
      "action_name": "auto-request_drawer_status",
      "description": "获取装载托盘/抽屉状态。",
      "description_en": "Get the loading tray/drawer status."
    },
    {
      "action_name": "auto-request_firmware_version",
      "description": "获取设备固件版本。",
      "description_en": "Get the device firmware version."
    },
    {
      "action_name": "auto-request_incubator_type",
      "description": "获取培养振荡单元的配置类型。",
      "description_en": "Get the incubator-shaker configuration type."
    },
    {
      "action_name": "auto-request_is_initialized",
      "description": "获取设备是否已初始化。",
      "description_en": "Get whether the device is initialized."
    },
    {
      "action_name": "auto-request_labware_detection_threshold",
      "description": "获取耗材检测阈值。",
      "description_en": "Get the labware detection threshold."
    },
    {
      "action_name": "auto-request_last_calibration_date",
      "description": "获取最近一次校准日期。",
      "description_en": "Get the last calibration date."
    },
    {
      "action_name": "auto-request_machine_allocation",
      "description": "获取指定堆叠层中已占用的设备槽位。",
      "description_en": "Get the occupied device slots on a selected stack layer."
    },
    {
      "action_name": "auto-request_maximum_allowed_temperature",
      "description": "获取最大允许温度或最高测得温度。",
      "description_en": "Get the maximum allowed temperature or the highest measured temperature."
    },
    {
      "action_name": "auto-request_number_of_connected_machines",
      "description": "获取指定层连接的设备数量。",
      "description_en": "Get the number of connected devices on a selected layer."
    },
    {
      "action_name": "auto-request_operation_time_in_hours",
      "description": "获取设备累计运行时间（小时）。",
      "description_en": "Get the total operating time in hours."
    },
    {
      "action_name": "auto-request_pid_controller_coefficients",
      "description": "获取温控 PID 系数。",
      "description_en": "Get the temperature-control PID coefficients."
    },
    {
      "action_name": "auto-request_plate_in_incubator",
      "description": "获取培养腔内是否有微孔板。",
      "description_en": "Get whether a plate is present in the incubator."
    },
    {
      "action_name": "auto-request_plate_status_known",
      "description": "获取微孔板在位状态是否已知。",
      "description_en": "Get whether the plate presence status is known."
    },
    {
      "action_name": "auto-request_serial_number",
      "description": "获取设备序列号。",
      "description_en": "Get the device serial number."
    },
    {
      "action_name": "auto-request_shaker_amplitude_x",
      "description": "获取 X 方向振荡幅度。",
      "description_en": "Get the shaker amplitude in the X direction."
    },
    {
      "action_name": "auto-request_shaker_amplitude_y",
      "description": "获取 Y 方向振荡幅度。",
      "description_en": "Get the shaker amplitude in the Y direction."
    },
    {
      "action_name": "auto-request_shaker_frequency_x",
      "description": "获取 X 方向振荡频率。",
      "description_en": "Get the shaker frequency in the X direction."
    },
    {
      "action_name": "auto-request_shaker_frequency_y",
      "description": "获取 Y 方向振荡频率。",
      "description_en": "Get the shaker frequency in the Y direction."
    },
    {
      "action_name": "auto-request_shaker_phase_shift",
      "description": "获取 X 与 Y 振荡之间的相位差。",
      "description_en": "Get the phase shift between X and Y shaking."
    },
    {
      "action_name": "auto-request_target_temperature",
      "description": "获取目标温度。",
      "description_en": "Get the target temperature."
    },
    {
      "action_name": "auto-request_thermal_calibration_date",
      "description": "获取热校准日期。",
      "description_en": "Get the thermal calibration date."
    },
    {
      "action_name": "auto-set_shaker_parameters",
      "description": "设置振荡器的幅度、频率和相位参数。",
      "description_en": "Set shaker amplitude, frequency, and phase parameters."
    },
    {
      "action_name": "auto-set_shaker_pattern",
      "description": "设置振荡运动模式及其参数。",
      "description_en": "Set the shaking motion pattern and its parameters."
    },
    {
      "action_name": "auto-set_shaker_status",
      "description": "启用或禁用振荡。",
      "description_en": "Enable or disable shaking."
    },
    {
      "action_name": "auto-shake",
      "description": "按选定模式配置并开始振荡。",
      "description_en": "Configure and start shaking with the selected pattern."
    },
    {
      "action_name": "auto-start_temperature_control",
      "description": "设置目标温度并启动温度控制。",
      "description_en": "Set the target temperature and start temperature control."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-stop_temperature_control",
      "description": "停止主动温度控制。",
      "description_en": "Stop active temperature control."
    },
    {
      "action_name": "auto-wait_for_temperature",
      "description": "等待设备达到目标温度。",
      "description_en": "Wait until the device reaches the target temperature."
    },
    {
      "action_name": "auto-number_of_connected_units",
      "description": "获取已连接单元数量。",
      "description_en": "Get the number of connected units."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送底层命令。",
      "description_en": "Send a low-level command to the device."
    },
    {
      "action_name": "auto-request_calibration_low",
      "description": "获取低点校准值。",
      "description_en": "Get the low-point calibration value."
    },
    {
      "action_name": "auto-request_calibration_high",
      "description": "获取高点校准值。",
      "description_en": "Get the high-point calibration value."
    },
    {
      "action_name": "auto-request_whole_calibration_data",
      "description": "读取完整校准数据。",
      "description_en": "Read the full calibration data."
    },
    {
      "action_name": "auto-request_proportionality_factor",
      "description": "获取比例因子。",
      "description_en": "Get the proportionality factor."
    },
    {
      "action_name": "auto-set_max_allowed_device_temperature",
      "description": "设置设备最大允许温度。",
      "description_en": "Set the maximum allowed device temperature."
    },
    {
      "action_name": "auto-set_pid_proportional_gain",
      "description": "设置 PID 比例增益。",
      "description_en": "Set the PID proportional gain."
    },
    {
      "action_name": "auto-set_pid_integration_value",
      "description": "设置 PID 积分值。",
      "description_en": "Set the PID integration value."
    },
    {
      "action_name": "auto-delete_counter",
      "description": "清除设备计数器。",
      "description_en": "Clear a device counter."
    },
    {
      "action_name": "auto-set_boost_offset",
      "description": "设置强化加热偏移量。",
      "description_en": "Set the boost offset."
    },
    {
      "action_name": "auto-set_boost_time",
      "description": "设置强化加热时间。",
      "description_en": "Set the boost time."
    },
    {
      "action_name": "auto-set_cooldown_time_factor",
      "description": "设置降温时间因子。",
      "description_en": "Set the cooldown time factor."
    },
    {
      "action_name": "auto-set_heatup_time_factor",
      "description": "设置升温时间因子。",
      "description_en": "Set the heat-up time factor."
    },
    {
      "action_name": "auto-set_heatup_offset",
      "description": "设置升温偏移量。",
      "description_en": "Set the heat-up offset."
    },
    {
      "action_name": "auto-set_calibration_low",
      "description": "设置低点校准值。",
      "description_en": "Set the low-point calibration value."
    },
    {
      "action_name": "auto-set_calibration_high",
      "description": "设置高点校准值。",
      "description_en": "Set the high-point calibration value."
    },
    {
      "action_name": "auto-reset_calibration_data",
      "description": "重置校准数据。",
      "description_en": "Reset the calibration data."
    },
    {
      "action_name": "auto-set_proportionality_factor",
      "description": "设置比例因子。",
      "description_en": "Set the proportionality factor."
    },
    {
      "action_name": "auto-request_motor_power_clockwise",
      "description": "获取顺时针方向电机功率设置。",
      "description_en": "Get the motor power setting for clockwise motion."
    },
    {
      "action_name": "auto-request_motor_power_anticlockwise",
      "description": "获取逆时针方向电机功率设置。",
      "description_en": "Get the motor power setting for anticlockwise motion."
    },
    {
      "action_name": "auto-request_motor_current_limit_clockwise",
      "description": "获取顺时针方向电机电流限制。",
      "description_en": "Get the motor current limit for clockwise motion."
    },
    {
      "action_name": "auto-request_motor_current_limit_anticlockwise",
      "description": "获取逆时针方向电机电流限制。",
      "description_en": "Get the motor current limit for anticlockwise motion."
    },
    {
      "action_name": "auto-set_motor_power_clockwise",
      "description": "设置顺时针方向电机功率。",
      "description_en": "Set the motor power for clockwise motion."
    },
    {
      "action_name": "auto-set_motor_power_anticlockwise",
      "description": "设置逆时针方向电机功率。",
      "description_en": "Set the motor power for anticlockwise motion."
    },
    {
      "action_name": "auto-set_motor_current_limit_clockwise",
      "description": "设置顺时针方向电机电流限制。",
      "description_en": "Set the motor current limit for clockwise motion."
    },
    {
      "action_name": "auto-set_motor_current_limit_anticlockwise",
      "description": "设置逆时针方向电机电流限制。",
      "description_en": "Set the motor current limit for anticlockwise motion."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取当前温度。",
      "description_en": "Get current temperature."
    },
    {
      "action_name": "auto-request_shaker_calibration_value",
      "description": "获取振荡器校准值。",
      "description_en": "Get the shaker calibration value."
    },
    {
      "action_name": "auto-read_whole_shaker_calibration_data",
      "description": "读取完整振荡器校准数据。",
      "description_en": "Read the full shaker calibration data."
    },
    {
      "action_name": "auto-set_shaker_calibration_value",
      "description": "设置振荡器校准值。",
      "description_en": "Set the shaker calibration value."
    }
  ]
}

